sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || !newValue) {
        return;
    }

    g_form.getReference('machine_ci', function(ci) {

        if (!ci) return;

        if (ci.location && ci.location.value) {
            g_form.setValue('location', ci.location.value);
        } else {
            g_form.setValue('location', ci.location);
        }

        if (ci.assignment_group && ci.assignment_group.value) {
            g_form.setValue('service_group', ci.assignment_group.value);
        } else {
            g_form.setValue('service_group', ci.assignment_group);
        }
    });
}
